+package com.example;
+
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.Span;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.RouterLink;
+import com.vaadin.flow.router.Route;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<ContactMessage> sentMessages = new Grid<>(ContactMessage.class, false);
+    private final MessageStore messageStore;
+    private boolean clearingForm;
+
+    public ContactView(MessageStore messageStore) {
+        this.messageStore = messageStore;
+
+        RouterLink about = new RouterLink("About", AboutView.class);
+        sentMessages.addColumn(ContactMessage::name).setHeader("Name");
+        sentMessages.addColumn(ContactMessage::message).setHeader("Message");
+
+        name.addValueChangeListener(event -> formWasEdited());
+        email.addValueChangeListener(event -> formWasEdited());
+        phone.addValueChangeListener(event -> formWasEdited());
+        message.addValueChangeListener(event -> formWasEdited());
+
+        send.addClickListener(event -> sendMessage());
+        send.addClickShortcut(Key.ENTER);
+
+        add(new H1("Contact"), about, name, email, phone, message, send, sentMessages);
+        refreshMessages();
+    }
+
+    private void formWasEdited() {
+        if (!clearingForm) {
+            send.setEnabled(true);
+        }
+    }
+
+    private void sendMessage() {
+        clearValidation();
+        boolean valid = true;
+
+        if (isBlank(name.getValue())) {
+            invalidate(name, "Name is required");
+            valid = false;
+        }
+        if (!isBlank(email.getValue()) && !isValidEmail(email.getValue())) {
+            invalidate(email, "Enter a valid e-mail address");
+            valid = false;
+        } else if (isBlank(email.getValue()) && isBlank(phone.getValue())) {
+            invalidate(email, "Give an e-mail address or a phone number");
+            valid = false;
+        }
+        if (isBlank(message.getValue())) {
+            invalidate(message, "Message is required");
+            valid = false;
+        } else if (message.getValue().length() > 500) {
+            invalidate(message, "Message must be at most 500 characters");
+            valid = false;
+        }
+
+        if (!valid) {
+            return;
+        }
+
+        messageStore.add(new ContactMessage(name.getValue(), email.getValue(),
+                phone.getValue(), message.getValue()));
+        refreshMessages();
+        clearingForm = true;
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        clearingForm = false;
+        send.setEnabled(false);
+        Notification.show("Message sent");
+    }
+
+    private void clearValidation() {
+        clearValidation(name);
+        clearValidation(email);
+        clearValidation(phone);
+        clearValidation(message);
+    }
+
+    private void clearValidation(com.vaadin.flow.component.HasValidation field) {
+        field.setInvalid(false);
+        field.setErrorMessage(null);
+    }
+
+    private void invalidate(com.vaadin.flow.component.HasValidation field,
+            String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+    }
+
+    private boolean isValidEmail(String value) {
+        // This is intentionally modest: the field accepts normal RFC-style
+        // addresses without making contact details unnecessarily restrictive.
+        return value.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
+    }
+
+    private boolean isBlank(String value) {
+        return value == null || value.isBlank();
+    }
+
+    private void refreshMessages() {
+        sentMessages.setItems(messageStore.all());
+    }
+
+    private boolean hasUnsavedInput() {
+        return !name.isEmpty() || !email.isEmpty() || !phone.isEmpty()
+                || !message.isEmpty();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasUnsavedInput()) {
+            return;
+        }
+
+        BeforeLeaveEvent.ContinueNavigationAction action = event.postpone();
+        Dialog dialog = new Dialog();
+        Button keepEditing = new Button("Keep editing", click -> dialog.close());
+        Button discard = new Button("Discard", click -> {
+            dialog.close();
+            action.proceed();
+        });
+        dialog.add(new Span("Discard the message you are editing?"), keepEditing, discard);
+        dialog.open();
+    }
+}
