+package com.example;
+
+import java.util.ArrayList;
+import java.util.List;
+
+import org.springframework.stereotype.Service;
+
+/**
+ * Application-scoped, in-memory messages. Keeping this outside the view means
+ * messages remain visible after a user navigates away and returns.
+ */
+@Service
+public class MessageStore {
+
+    private final List<ContactMessage> messages = new ArrayList<>();
+
+    public synchronized void add(ContactMessage message) {
+        messages.addFirst(message);
+    }
+
+    public synchronized List<ContactMessage> all() {
+        return List.copyOf(messages);
+    }
+}
